# Their timestamps are US Eastern (verified on three calls against our UTC
# rows and the Asterisk CDR: 15:59:28 EDT == 19:59:23 UTC).
EDT = tzmod(timedelta(hours=-4))

matched = missing = dur_close = dur_far = 0
ttc_ours_zero = 0
worst = []
for t in THEIRS:
    at = datetime.strptime(t['at'], '%Y-%m-%d %H:%M:%S').replace(tzinfo=EDT)
    digits = t['caller'][-10:]
    ours = (CallRecord.objects
            .filter(caller_number__endswith=digits,
                    created_at__gte=at - timedelta(minutes=6),
                    created_at__lte=at + timedelta(minutes=6))
            .order_by('created_at').first())
    if ours is None:
        missing += 1
        if missing <= 8:
            print(f"NOT IN OURS: {t['caller']} at {t['at']} their-dur={t['dur']}s {t['status']}")
        continue
    matched += 1
    diff = abs((ours.duration_seconds or 0) - t['dur'])
    if diff <= 5:
        dur_close += 1
    else:
        dur_far += 1
        if len(worst) < 8:
            worst.append(f"  {t['caller']} {t['at']}: ours {ours.duration_seconds}s vs theirs {t['dur']}s")
    if ours.answered_at:
        start = ours.started_at or ours.created_at
        if int((ours.answered_at - start).total_seconds()) <= 1:
            ttc_ours_zero += 1

print(f"\ntheir rows: {len(THEIRS)} | matched in our log: {matched} | not found: {missing}")
print(f"duration agrees within 5s: {dur_close} | differs more: {dur_far}")
if worst:
    print('largest duration differences:')
    for w in worst: print(w)
print(f"of matched answered calls, ours shows TTC 0 on: {ttc_ours_zero}")
print(f"their TTC range on the same calls: {min(t['ttc'] for t in THEIRS)}-{max(t['ttc'] for t in THEIRS)}s")
print("\nsame calls when matched+durations agree; the TTC gap is the two-leg split (CH-119)")
